// A4Q3 Hell's Forge — Q28_TimerCallback_DropForgeRunes: the forge reward drop, fired by a scheduled event after the smash. Drops nItemsToDrop gems each pass — gem code chosen per difficulty (Act3/Act2/Act1 gem-code tables = hell/nm/normal) from the quest control seed — decrementing the gem-quality counter each pass and re-scheduling itself until exhausted; on the final pass (expansion only) also drops one rune from the per-difficulty rune table (normal r01-r11, nightmare r12-r22, hell r15-r25). This is the classic Hell's Forge gem+rune reward. No QuestRecord writes (drops only).
void __fastcall Q28_TimerCallback_DropForgeRunes(D2QuestDataStrc * pQuestData, D2UnitStrc * pUnit) {
    // Static local variables (originally global data)
    static uint32_t aRunesListNomal[11] = {
    0x20313072,
    0x20323072,
    0x20333072,
    0x20343072,
    0x20353072,
    0x20363072,
    0x20373072,
    0x20383072,
    0x20393072,
    0x20303172,
    0x20313172
}; D2_STATIC_GUARD(aRunesListNomal, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::aRunesListNomal");
    static uint32_t aRunesListNightmare[11] = {
    0x20323172,
    0x20333172,
    0x20343172,
    0x20353172,
    0x20363172,
    0x20373172,
    0x20383172,
    0x20393172,
    0x20303272,
    0x20313272,
    0x20323272
}; D2_STATIC_GUARD(aRunesListNightmare, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::aRunesListNightmare");
    static uint32_t aRunesListHell[11] = {
    0x20353172,
    0x20363172,
    0x20373172,
    0x20383172,
    0x20393172,
    0x20303272,
    0x20313272,
    0x20323272,
    0x20333272,
    0x20343272,
    0x20353272
}; D2_STATIC_GUARD(aRunesListHell, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::aRunesListHell");
    static uint32_t Q28_aForgeRuneCodesAct1[7] = { 0x20767067, 0x20727067, 0x20627067, 0x20797067, 0x20677067, 0x20777067, 0x207a6b73 }; D2_STATIC_GUARD(Q28_aForgeRuneCodesAct1, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::Q28_aForgeRuneCodesAct1");
    static uint32_t Q28_aForgeRuneCodesAct2[7] = { 0x20767a67, 0x20726c67, 0x20626c67, 0x20796c67, 0x20676c67, 0x20776c67, 0x206c6b73 }; D2_STATIC_GUARD(Q28_aForgeRuneCodesAct2, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::Q28_aForgeRuneCodesAct2");
    static uint32_t Q28_aForgeRuneCodesAct3[7] = { 0x20767367, 0x20727367, 0x20627367, 0x20797367, 0x20677367, 0x20777367, 0x20756b73 }; D2_STATIC_GUARD(Q28_aForgeRuneCodesAct3, "D2Game::Quests::QUESTS::A4Q3::Q28_TimerCallback_DropForgeRunes::Q28_aForgeRuneCodesAct3");

    D2SeedStrc* pSeed;
    uint32_t aRuneCode;
    uint32_t nRuneIdx;
    int nRngMod;
    uint32_t* pRuneTable;
    char aGemItemCode[4];
    ::SGAMEDATA* pGame;
    D2SeedStrc sSeedNext;
    D2QuestDataA4Q3Strc* pQuestSpecificData = pQuestData->pQuestSpecificData.pA4Q3;
    if (pQuestSpecificData->bSetupUpdateFlag) {
      D2Common::Units::SetupUpdateFlag(pUnit, 4);
    }
    if (!pQuestSpecificData->bDropActive) {
      return;
    }

    aGemItemCode[0] = '2';
    aGemItemCode[1] = '\0';
    aGemItemCode[2] = '\0';
    aGemItemCode[3] = '\0';
    int nDropsSucceeded = 0;
    int iDropPass = 0;
    if (pQuestSpecificData->nItemsToDrop <= 0) {
      return;
    }

    do {
      D2UnitStrc* pDroppedGem;
      switch (pQuestSpecificData->nGemQuality) {
        case 4:
          pSeed = GetQuestControlSeed(pQuestData->pGame);
        sSeedNext = D2_SEED_NEXT(*pSeed);
        nRngMod = (int)((uint64_t)sSeedNext.nSeedLow * 0x24924925 >> 0x20);
        *pSeed = sSeedNext;
        aRuneCode = Q28_aForgeRuneCodesAct1[((sSeedNext.nSeedLow - nRngMod >> 1) + nRngMod >> 2) * -7 + sSeedNext.nSeedLow];
        break;
        default:
          return;
        case 2:

        case 3:
          pSeed = GetQuestControlSeed(pQuestData->pGame);
        sSeedNext = D2_SEED_NEXT(*pSeed);
        nRngMod = (int)((uint64_t)sSeedNext.nSeedLow * 0x24924925 >> 0x20);
        *pSeed = sSeedNext;
        aRuneCode = Q28_aForgeRuneCodesAct2[((sSeedNext.nSeedLow - nRngMod >> 1) + nRngMod >> 2) * -7 + sSeedNext.nSeedLow];
        break;
        case 1:
          pSeed = GetQuestControlSeed(pQuestData->pGame);
        sSeedNext = D2_SEED_NEXT(*pSeed);
        nRngMod = (int)((uint64_t)sSeedNext.nSeedLow * 0x24924925 >> 0x20);
        *pSeed = sSeedNext;
        aRuneCode = Q28_aForgeRuneCodesAct3[((sSeedNext.nSeedLow - nRngMod >> 1) + nRngMod >> 2) * -7 + sSeedNext.nSeedLow];
        break;
      }

      pUnit->dwDropItemCode = aRuneCode;
      pDroppedGem = ITEMS::Items::Drop::ITEM_RewardItemToDrop(pQuestData->pGame, pUnit, ITEMTYPE_Shield, (int32_t*)aGemItemCode, nullptr, -1, 0);
      if (pDroppedGem) {
        nDropsSucceeded++;
      }

      iDropPass++;
    } while (iDropPass < pQuestSpecificData->nItemsToDrop);

    if (!nDropsSucceeded) {
      return;
    }

    pQuestSpecificData->nGemQuality--;
    if (pQuestSpecificData->nGemQuality <= 0) {
      pQuestSpecificData->bDropActive = 0;
      pGame = pQuestData->pGame;
      if (pGame->bExpansion) {
        pRuneTable = aRunesListNomal;
        if (pGame->nDifficulty != 1) {
          if (pGame->nDifficulty == 2) {
            pRuneTable = aRunesListHell;
          }
        } else {
          pRuneTable = aRunesListNightmare;
        }

        pSeed = GetQuestControlSeed(pGame);
        nRuneIdx = D2Client::Archive::UNIT_GetModuloFromSeed(pSeed, 0xb);
        pUnit->dwDropItemCode = pRuneTable[nRuneIdx];
        ITEMS::Items::Drop::ITEM_RewardItemToDrop(pQuestData->pGame, pUnit, ITEMTYPE_Shield, (int32_t*)aGemItemCode, nullptr, -1, 0);
        return;
      }
    } else {
      GAME::Event::SetEvent(pQuestData->pGame, pUnit, 7, pQuestData->pGame->dwGameFrame + 0x14, 0, 0);
    }
}

